def _write_part(out, v, depth):
    _closed_enum(PartKind, v.kind)
    out += b"{"
    out += b"\n"
    _pad(out, depth + 1)
    _esc(out, "kind")
    out += b": "
    _esc(out, v.kind)
    if v.text:
        out += b","
        out += b"\n"
        _pad(out, depth + 1)
        _esc(out, "text")
        out += b": "
        _esc(out, v.text)
    if v.digest:
        out += b","
        out += b"\n"
        _pad(out, depth + 1)
        _esc(out, "digest")
        out += b": "
        _esc(out, v.digest)
    if v.media_type:
        out += b","
        out += b"\n"
        _pad(out, depth + 1)
        _esc(out, "media_type")
        out += b": "
        _esc(out, v.media_type)
    if v.call_id:
        out += b","
        out += b"\n"
        _pad(out, depth + 1)
        _esc(out, "call_id")
        out += b": "
        _esc(out, v.call_id)
    if v.name:
        out += b","
        out += b"\n"
        _pad(out, depth + 1)
        _esc(out, "name")
        out += b": "
        _esc(out, v.name)
    if v.arguments:
        out += b","
        out += b"\n"
        _pad(out, depth + 1)
        _esc(out, "arguments")
        out += b": "
        _esc(out, v.arguments)
    out += b"\n"
    _pad(out, depth)
    out += b"}"


def _write_message(out, v, depth):
    _closed_enum(Role, v.role)
    out += b"{"
    out += b"\n"
    _pad(out, depth + 1)
    _esc(out, "role")
    out += b": "
    _esc(out, v.role)
    out += b","
    out += b"\n"
    _pad(out, depth + 1)
    _esc(out, "parts")
    out += b": "
    _write_list(out, v.parts, depth + 1, _write_part)
    out += b"\n"
    _pad(out, depth)
    out += b"}"


def _write_tool(out, v, depth):
    out += b"{"
    out += b"\n"
    _pad(out, depth + 1)
    _esc(out, "name")
    out += b": "
    _esc(out, v.name)
    out += b","
    out += b"\n"
    _pad(out, depth + 1)
    _esc(out, "description")
    out += b": "
    _esc(out, v.description)
    out += b","
    out += b"\n"
    _pad(out, depth + 1)
    _esc(out, "parameters")
    out += b": "
    _esc(out, v.parameters)
    out += b"\n"
    _pad(out, depth)
    out += b"}"


def _write_temperature(out, v, depth):
    out += b"{"
    out += b"\n"
    _pad(out, depth + 1)
    _esc(out, "milli")
    out += b": "
    _num(out, v.milli)
    out += b"\n"
    _pad(out, depth)
    out += b"}"


def _write_options(out, v, depth):
    out += b"{"
    first = True
    if v.max_output != 0:
        first = False
        out += b"\n"
        _pad(out, depth + 1)
        _esc(out, "max_output")
        out += b": "
        _num(out, v.max_output)
    if v.temperature is not None:
        if not first:
            out += b","
        first = False
        out += b"\n"
        _pad(out, depth + 1)
        _esc(out, "temperature")
        out += b": "
        _write_temperature(out, v.temperature, depth + 1)
    if v.stop:
        if not first:
            out += b","
        first = False
        out += b"\n"
        _pad(out, depth + 1)
        _esc(out, "stop")
        out += b": "
        _strs(out, v.stop, depth + 1)
    if v.json_schema:
        if not first:
            out += b","
        first = False
        out += b"\n"
        _pad(out, depth + 1)
        _esc(out, "json_schema")
        out += b": "
        _esc(out, v.json_schema)
    if not first:
        out += b"\n"
        _pad(out, depth)
    out += b"}"


def _write_request(out, v, depth):
    for item in v.guarantees:
        if not isinstance(item, str):
            raise Refusal("wrong_type", 0)
    out += b"{"
    out += b"\n"
    _pad(out, depth + 1)
    _esc(out, "model")
    out += b": "
    _esc(out, v.model)
    out += b","
    out += b"\n"
    _pad(out, depth + 1)
    _esc(out, "messages")
    out += b": "
    _write_list(out, v.messages, depth + 1, _write_message)
    if v.tools:
        out += b","
        out += b"\n"
        _pad(out, depth + 1)
        _esc(out, "tools")
        out += b": "
        _write_list(out, v.tools, depth + 1, _write_tool)
    if v.options is not None:
        out += b","
        out += b"\n"
        _pad(out, depth + 1)
        _esc(out, "options")
        out += b": "
        _write_options(out, v.options, depth + 1)
    if v.extensions:
        out += b","
        out += b"\n"
        _pad(out, depth + 1)
        _esc(out, "extensions")
        out += b": "
        _strmap(out, v.extensions, depth + 1)
    if v.required_extensions:
        out += b","
        out += b"\n"
        _pad(out, depth + 1)
        _esc(out, "required_extensions")
        out += b": "
