class Transcription:
    """Prerecorded speech-to-text over an authorized content digest. Operations use
    the shared retained-delta lifecycle and are visible only through this
    profile to the account and program that started them."""

    def start(self, request: TranscriptionRequest) -> Admission:
        """Admit one prerecorded transcription for the bound caller. Admission
        follows chat order for profile transcription: arguments, host and
        wire/format support, complete rights, authorized bounded content
        resolution and verification, ceiling, capacity, then the profile-scoped
        hosted credential. Nothing leaves the service before all checks pass."""
        raise NotImplementedError

    def observe(self, operation: str, cursor: int, max_deltas: int, max_bytes: int, wait_ms: int) -> DeltaPage:
        """Read retained segment and terminal deltas with the shared operation
        cursor, page, reconnect, wait and idle semantics."""
        raise NotImplementedError

    def cancel(self, operation: str) -> Cancellation:
        """Stop a transcription operation and close its upstream request, using the
        shared operation cancellation outcomes."""
        raise NotImplementedError


