class Live:
    """Live audio through bounded native IPC calls. One session produces one final
    response. A new response starts a new session. Credentials and vendor
    WebSockets stay in the service."""

    def start(self, request: LiveRequest) -> Admission:
        """Admit a live session after host support, complete permission,
        output-write preflight, budget, shared capacity and credential checks.
        The service owns the upstream session. Observe reports setup failures
        after admission."""
        raise NotImplementedError

    def append(self, operation: str, sequence: int, audio: bytes) -> LiveInputResult:
        """Append 1..65536 even-sized PCM bytes at the expected sequence. Bounded
        input and idle limits apply. Concurrent appends are serialized; only
        confirmed sends advance next_sequence."""
        raise NotImplementedError

    def observe(self, operation: str, cursor: int, max_deltas: int, max_bytes: int, wait_ms: int) -> DeltaPage:
        """Read retained transcript, audio and terminal deltas using shared cursor
        and wait semantics."""
        raise NotImplementedError

    def commit(self, operation: str) -> LiveInputResult:
        """Close input and request the final response. A repeated Commit is
        duplicate. Observe continues until terminal delivery or failure; Commit
        does not wait for synthesis to finish."""
        raise NotImplementedError

    def cancel(self, operation: str) -> Cancellation:
        """Immediately stop the live session and its upstream connection. Uses
        shared operation cancellation and ownership semantics."""
        raise NotImplementedError


